//! What the Python tools printed, ran with and wrote on each input here: the
//! run the Rust is held to. Written once from a real run of the Python, which
//! has since gone; `MEASUREMENTS.md`, "The Linux tools are examples", has how.

/// One run of one tool.
pub struct Case {
    /// The tool's name.
    pub tool: &'static str,
    /// What the input is.
    pub name: &'static str,
    /// The files it was given.
    pub files: &'static [(&'static str, &'static [u8])],
    /// The directories it was given.
    pub dirs: &'static [&'static str],
    /// Its arguments, `{D}` the folder the files are in.
    pub args: &'static [&'static str],
    /// Its stdin.
    pub stdin: &'static [u8],
    /// Its stdout.
    pub stdout: &'static [u8],
    /// Its exit code.
    pub code: i32,
    /// The files it wrote, and each one's SHA-256.
    pub made: &'static [(&'static str, &'static str)],
}

